const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let sign = 1;
        if (buffer[offset] === 45) { // '-'
            sign = -1;
            offset++;
        }
        let res = 0;
        while (offset < buffer.length && buffer[offset] >= 48 && buffer[offset] <= 57) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res * sign;
    }

    const N = readInt();
    if (N === null) return;
    const Q = readInt();
    const K = readInt();

    const A = new Int32Array(N + 1);
    const X = new Float64Array(N + 1);
    const Y = new Float64Array(N + 1);

    const mapX = new Map();
    const mapY = new Map();

    for (let i = 1; i <= N; i++) {
        A[i] = readInt();
        X[i] = i - A[i];
        Y[i] = i + A[i];

        let arrX = mapX.get(X[i]);
        if (!arrX) {
            arrX = [];
            mapX.set(X[i], arrX);
        }
        arrX.push(i);

        let arrY = mapY.get(Y[i]);
        if (!arrY) {
            arrY = [];
            mapY.set(Y[i], arrY);
        }
        arrY.push(i);
    }

    const T = new Int32Array(N + 1);
    for (let t = 1; t <= Q; t++) {
        const d = readInt();
        T[d] = t;
    }

    let nextT = Q + 1;
    for (let i = 1; i <= N; i++) {
        if (T[i] === 0) {
            T[i] = nextT++;
        }
    }

    // Construção da Árvore Cartesiana (min-heap em T)
    const left = new Int32Array(N + 1);
    const right = new Int32Array(N + 1);
    const stack = new Int32Array(N + 1);
    let top = 0;

    for (let i = 1; i <= N; i++) {
        let last = 0;
        while (top > 0 && T[stack[top]] > T[i]) {
            last = stack[top--];
        }
        if (top > 0) {
            right[stack[top]] = i;
        }
        left[i] = last;
        stack[++top] = i;
    }
    const root = stack[1];

    // Travessia iterativa para obter a pós-ordem
    const order = new Int32Array(N);
    let orderPtr = 0;
    const s = new Int32Array(N + 1);
    let sTop = 0;
    s[++sTop] = root;

    while (sTop > 0) {
        const u = s[sTop--];
        order[orderPtr++] = u;
        if (left[u] !== 0) s[++sTop] = left[u];
        if (right[u] !== 0) s[++sTop] = right[u];
    }

    function countInRange(arr, l, r) {
        if (!arr || l > r) return 0;
        let low = 0, high = arr.length;
        while (low < high) {
            const mid = (low + high) >> 1;
            if (arr[mid] >= l) high = mid;
            else low = mid + 1;
        }
        const idxL = low;

        low = 0; high = arr.length;
        while (low < high) {
            const mid = (low + high) >> 1;
            if (arr[mid] > r) high = mid;
            else low = mid + 1;
        }
        const idxR = low;

        return idxR - idxL;
    }

    const L = new Int32Array(N + 1);
    const R = new Int32Array(N + 1);
    const deaths = new Float64Array(Q + 2);
    let totalPairs = 0;

    // Processa os nós em pós-ordem
    for (let idx = N - 1; idx >= 0; idx--) {
        const u = order[idx];
        const l = left[u];
        const r = right[u];
        const Lu = (l !== 0) ? L[l] : u;
        const Ru = (r !== 0) ? R[r] : u;
        L[u] = Lu;
        R[u] = Ru;

        const SL = u - Lu + 1;
        const SR = Ru - u + 1;

        let count_u = 0;

        if (SL <= SR) {
            for (let i = Lu; i <= u; i++) {
                const j_min = (i === u) ? u + 1 : u;

                // Condição 1: X_j = X_i + K e j <= i + K
                const max_j1 = Math.min(Ru, i + K);
                if (j_min <= max_j1) {
                    const arr = mapX.get(X[i] + K);
                    if (arr !== undefined) {
                        count_u += countInRange(arr, j_min, max_j1);
                    }
                }

                // Condição 2: Y_j = Y_i + K e j < i + K (j <= i + K - 1)
                const max_j2 = Math.min(Ru, i + K - 1);
                if (j_min <= max_j2) {
                    const arr = mapY.get(Y[i] + K);
                    if (arr !== undefined) {
                        count_u += countInRange(arr, j_min, max_j2);
                    }
                }
            }
        } else {
            for (let j = u; j <= Ru; j++) {
                const i_max = (j === u) ? u - 1 : u;

                // Condição 1: X_i = X_j - K e i >= j - K
                const min_i1 = Math.max(Lu, j - K);
                if (min_i1 <= i_max) {
                    const arr = mapX.get(X[j] - K);
                    if (arr !== undefined) {
                        count_u += countInRange(arr, min_i1, i_max);
                    }
                }

                // Condição 2: Y_i = Y_j - K e i > j - K (i >= j - K + 1)
                const min_i2 = Math.max(Lu, j - K + 1);
                if (min_i2 <= i_max) {
                    const arr = mapY.get(Y[j] - K);
                    if (arr !== undefined) {
                        count_u += countInRange(arr, min_i2, i_max);
                    }
                }
            }
        }

        if (T[u] <= Q) {
            deaths[T[u]] += count_u;
        }
        totalPairs += count_u;
    }

    let out = '';
    let current = totalPairs;
    out += current.toString() + '\n';
    for (let t = 1; t <= Q; t++) {
        current -= deaths[t];
        out += current.toString() + '\n';
        if (out.length > 65536) {
            process.stdout.write(out);
            out = '';
        }
    }
    if (out.length > 0) {
        process.stdout.write(out);
    }
}

